/* Generated by tools/build_site.py from catalog.json - do not edit. */
window.PLAYGROUND_SEARCH = [
{t:"Select Similar",p:"Model > Select",u:"model-select-select-similar.html",b:"Selects every item that shares the property values you tick with the first selected item, in the whole model, its own model or the selection."},
{t:"Filter Selection",p:"Model > Select",u:"model-select-filter-selection.html",b:"Keeps or removes the selected items whose property passes a test (equals, contains, greater than, is missing...) without running a new search."},
{t:"Invert",p:"Model > Select",u:"model-select-quick-invert.html",b:"Selects everything the current selection leaves out, leaving hidden items out. With nothing selected it selects everything visible. Shift+Click for settings."},
{t:"Select by File",p:"Model > Select",u:"model-select-quick-select-by-file.html",b:"Selects every item of the appended files you tick, remembering your last choice. Shift+Click for settings."},
{t:"Save as Set",p:"Model > Select",u:"model-select-quick-save-as-set.html",b:"Saves the current selection as a selection set named from a template such as Ducts - 412 items - 2026-10-05, in the Playground folder. Shift+Click for settings."},
{t:"Back",p:"Model > Select",u:"model-select-history-back.html",b:"Restores the selection you had before this one, like Back in a browser. After clearing the selection it brings the last one back."},
{t:"Forward",p:"Model > Select",u:"model-select-history-forward.html",b:"Restores the next selection after going Back."},
{t:"History",p:"Model > Select",u:"model-select-history-history-list.html",b:"Lists the selections made in this model (time, item count, main category) and restores the one you choose. Shift+Click for settings."},
{t:"Pick Order",p:"Model > Select",u:"model-select-pick-order.html",b:"Records the items you click, in the order you click them, so you can select, number, export or color them in that order. Click it, then click items one at a time (Ctrl+click works too); the bar along the bottom of the window counts them."},
{t:"Select Picked",p:"Model > Select",u:"model-select-pick-order-actions-select-picked.html",b:"Selects the items in the pick list."},
{t:"Number Picked",p:"Model > Select",u:"model-select-pick-order-actions-number-picked.html",b:"Writes Playground > Sequence = 1, 2, 3... onto the picked items in pick order, keeping their other Playground properties. One undo step."},
{t:"Export Picked",p:"Model > Select",u:"model-select-pick-order-actions-export-picked.html",b:"Writes the pick list to Excel or CSV: order, name, category, Element ID, GUID, source file and centre point in model units."},
{t:"Color Picked",p:"Model > Select",u:"model-select-pick-order-actions-color-picked.html",b:"Colors the picked items from light to strong blue along the pick order. One undo step."},
{t:"Clear Picked",p:"Model > Select",u:"model-select-pick-order-actions-clear-picked.html",b:"Empties the pick list of this model."},
{t:"Quick Find",p:"Model > Find",u:"model-find-quick-find.html",b:"Finds any element by name, Element ID, category, type, mark or level as you type. Enter selects and zooms, Shift+Enter selects every match. Shift+Click for settings."},
{t:"Search Set Wizard",p:"Model > Find",u:"model-find-search-set-wizard.html",b:"Builds a search set step by step: where to search, conditions picked from the model's own properties and values, a live count, then name and folder."},
{t:"Batch Sets",p:"Model > Find",u:"model-find-batch-sets.html",b:"Creates one search set per value of a property, such as one set per level, named and foldered from templates. One undo step."},
{t:"Sets Library",p:"Model > Find",u:"model-find-sets-library.html",b:"Publishes search sets to a shared library and imports them into other models, or renames and deletes libraries."},
{t:"Export Sets",p:"Model > Find",u:"model-find-set-exchange-export-sets.html",b:"Writes the sets you choose to a Playground XML file: search sets as conditions, selection sets as item references that survive into other files."},
{t:"Import Sets",p:"Model > Find",u:"model-find-set-exchange-import-sets.html",b:"Recreates sets and folders from a Playground XML file, finding static set items by path, GUID or Element ID, and reports what was found."},
{t:"Repair Search In",p:"Model > Find",u:"model-find-set-exchange-search-in-repair.html",b:"Finds search sets whose Search In scope is empty or points at models that are gone, and re-scopes them to matching models or the whole model."},
{t:"What Is It",p:"Model > Inspect",u:"model-inspect-what-is-it.html",b:"Everything Navisworks knows about one item in one card: identity, Revit IDs, source file and tree path, size and position, geometry, colour and state, and every property tab. Select the item first, or click it in the view when nothing is selected. A plain-text summary goes to the clipboard."},
{t:"Properties Plus",p:"Model > Inspect",u:"model-inspect-properties-plus.html",b:"A window that follows the selection: pinned properties compared across every selected item (one value, or how many differ), and all of the first item's properties. Copy a value or select every item in the model that shares it."},
{t:"Selection HUD",p:"Model > Inspect",u:"model-inspect-selection-hud.html",b:"Shows a small readout in the bottom-left corner of the Navisworks window: how many items and objects are selected, from which models, the top categories, and a summed property when you set one. Shift+Click for settings."},
{t:"Copy IDs",p:"Model > Inspect",u:"model-inspect-inspect-tools-copy-ids.html",b:"Copies one row per selected element (name, Element ID, UniqueId, IFC GlobalId, InstanceGuid, source file, tree path) as tab-separated text with a header, ready to paste into Excel. Shift+Click for settings."},
{t:"Open in Explorer",p:"Model > Inspect",u:"model-inspect-inspect-tools-open-in-explorer.html",b:"Shows the selected item's model file in Windows Explorer: the source file it was appended from, or its Navisworks cache file (asks when both exist). With nothing selected, shows this document's own file."},
{t:"Property Explorer",p:"Model > Data",u:"model-data-property-explorer.html",b:"Scans the selection, the visible items or the whole model once, then lists every category, property and value with counts in three linked, searchable lists. Select the items with a value, save it as a search set, copy the list or export the whole index to Excel."},
{t:"Count by Property",p:"Model > Data",u:"model-data-count-by-property.html",b:"Counts objects by the values of one property, or by pairs of values of two (a two-level pivot), over the selection, the visible items or the whole model. Shows a sorted table with shares and a top 20 chart, then lets you select any group. Optional Excel export."},
{t:"Property Exporter",p:"Model > Data",u:"model-data-property-exporter.html",b:"Exports the properties you tick for the selected objects (or their geometry items) to a styled Excel workbook or a CSV file, with name, file, Element ID and GUID columns in front. Your choice is remembered and can be saved as a named template."},
{t:"Data Validator",p:"Model > Data",u:"model-data-data-validator.html",b:"Checks the model against BEP rules kept as JSON files in the team rules folder (every duct has a system name, every element a level, marks filled in, comments matching a pattern). Reports passes and failures per rule with element links, and can export to Excel and save a selection set per failing rule. Shift+Click for settings."},
{t:"Bulk Property Writer",p:"Model > Data",u:"model-data-write-data-bulk-property-writer.html",b:"Writes up to 10 custom properties to the selected items in one step, merged into an existing tab, or writes a spreadsheet's columns to the objects its Element ID, GUID or property column matches, with a preview of matched, unmatched and ambiguous rows first."},
{t:"Find and Replace",p:"Model > Data",u:"model-data-write-data-find-and-replace.html",b:"Finds text or a regular expression in property values (all properties or one) and replaces it after a preview. Native values are read-only, so corrections go to a Playground Corrected tab; values in custom tabs are edited in place."},
{t:"Property Mapper",p:"Model > Data",u:"model-data-write-data-property-mapper.html",b:"Fills one standard tab (System, Level, Mark...) from whichever source property each model uses, in order of preference, with optional regex clean-up and per-model overrides. Shows coverage per field and model before writing. Profiles are team-shareable and export to JSON."},
{t:"External Data Link",p:"Model > Data",u:"model-data-write-data-external-data-link.html",b:"Links a spreadsheet to this document by a key column (Element ID, GUID or a property) and writes its columns to a custom tab on the matched objects. Refresh re-reads the file and reports matched, unmatched and changed; links are saved with the document's Playground data."},
{t:"Model Tree Export",p:"Model > Data",u:"model-data-data-tools-model-tree-export.html",b:"Exports the selection tree to a chosen depth (4 by default) as an Excel workbook with a sheet per model: each node's depth, name, class, descendants, geometry items and hidden state, indented and one column per level so it filters in Excel."},
{t:"Clear Labels",p:"Model > Data",u:"model-data-data-tools-clear-labels.html",b:"Removes the value labels Property Labels drew in the view."},
{t:"Property Labels",p:"Model > Data",u:"model-data-property-labels.html",b:"Draws a chosen property's value above each selected object in the view, on a short leader from the top of its box (up to 500 objects). Labels follow orbit and zoom; Clear Labels removes them."},
{t:"Color by Property",p:"Model > Look",u:"model-look-color-by-property.html",b:"Colors every item by the value of a property you pick, most common values first, and lists the legend with counts. The same value keeps its color from one run to the next."},
{t:"Color Presets",p:"Model > Look",u:"model-look-color-presets.html",b:"Saves a color scheme as a named preset the whole team can apply, then repaints the model from it in one step. Manage renames, deletes, exports and imports presets."},
{t:"Trade Ghost",p:"Model > Look",u:"model-look-trade-ghost.html",b:"Keeps the trades you choose, or the selection, solid and fades every other model to a transparent grey. Click again to change the focus or clear the ghost. Shift+Click for settings."},
{t:"Status Painter",p:"Model > Look",u:"model-look-status-painter.html",b:"Paints items by construction status (Installed, In progress, Planned, On hold, Issue), sets the status of the selection, and shows the legend. Shift+Click for settings."},
{t:"Legend Maker",p:"Model > Look",u:"model-look-look-tools-legend-maker.html",b:"Draws the last color scheme as a print-ready PNG legend with swatches and counts, and can save a viewpoint that brings those colors back."},
{t:"Match Appearance",p:"Model > Look",u:"model-look-look-tools-match-appearance.html",b:"Copies the color and transparency of the first selected item to the rest of the selection. With one item selected, or none, click the objects to paint one by one and press Esc to finish."},
{t:"Exploded View",p:"Model > Look",u:"model-look-look-tools-exploded-view.html",b:"Spreads the selected objects or their models away from their common center as one undoable move, without touching the source files. Click again to collapse them back or spread them further."},
{t:"Reset Overrides",p:"Model > Look",u:"model-look-view-tools-reset-all-overrides.html",b:"Puts back the model colors, transparency, hidden items, moved items or required and frozen flags you choose, all in one undo step."},
{t:"Background",p:"Model > Look",u:"model-look-view-tools-background.html",b:"Steps the view background through White, Light gradient, Dark gradient, Black and Horizon. Shift+Click picks one from the list or a custom color."},
{t:"Presentation Mode",p:"Model > Look",u:"model-look-presentation-mode.html",b:"Clears the screen for a meeting by minimizing the ribbon to its tabs, closing add-in panels and maximizing the window. Click again or press Ctrl+Alt+F11 to put everything back. Shift+Click for settings."},
{t:"Exit Presentation",p:"Model > Look",u:"model-look-exit-presentation.html",b:"Leaves Presentation Mode and puts the ribbon, panels, window size and background back from anywhere."},
{t:"Batch Viewpoints",p:"Views > Viewpoints",u:"views-viewpoints-batch-viewpoints.html",b:"Saves a viewpoint for every level, grid intersection, selection or search set, or model in one go: plans cut at each level, eye-level views or zoomed sets, named and filed by template. One Ctrl+Z removes the batch."},
{t:"Viewpoints from Excel",p:"Views > Viewpoints",u:"views-viewpoints-viewpoints-from-excel.html",b:"Exports saved viewpoints to an Excel workbook (folder, name, eye, target, up, lens, comment) in model units, or creates and updates viewpoints from one by folder and name."},
{t:"Export Viewpoints",p:"Views > Viewpoints",u:"views-viewpoints-export-viewpoints.html",b:"Exports only the saved viewpoints you tick, as a Navisworks viewpoints XML file for Import Viewpoints, or as a Playground package that keeps cameras, sections and comments for Viewpoint Sync."},
{t:"Viewpoint Sync",p:"Views > Viewpoints",u:"views-viewpoints-viewpoint-sync.html",b:"Copies viewpoint folders from one Navisworks file to another through a package: export the folders here, import them there into the folder you choose, skipping, replacing or keeping both when a name exists."},
{t:"Where Am I",p:"Views > Viewpoints",u:"views-viewpoints-where-am-i.html",b:"One popup with where the camera is: the saved viewpoint it is on, eye coordinates, compass heading and pitch, nearest level and grid intersection, lens, section, models and selection. Copy puts it on the clipboard."},
{t:"Viewpoints to Images",p:"Views > Capture",u:"views-capture-viewpoints-to-images.html",b:"Saves an image of every viewpoint you choose (PNG or JPG, 720p to 4K or a custom size, named by template) into a dated folder with an index.html contact sheet. Your view comes back afterwards."},
{t:"Batch Images",p:"Views > Capture",u:"views-capture-batch-image-export.html",b:"Saves images of saved viewpoints, clash results (by test and status) and Playground issues in one run, into Viewpoints, Clashes and Issues folders with one index.html contact sheet."},
{t:"Batch PDF",p:"Views > Capture",u:"views-capture-batch-pdf.html",b:"Prints the viewpoints you choose, in folder order or your own order, to one PDF handout: title page, contents, one page per view with its comments and a footer. A4, A3, Letter or Tabloid."},
{t:"Level Sectioner",p:"Views > Navigate",u:"views-navigate-level-sectioner.html",b:"Cuts the model at the level you choose: a section plane at the cut height above the floor, optionally the floors below hidden and a plan view. Levels come from the grid system or are estimated from the model. Shift+Click for settings."},
{t:"Level Up",p:"Views > Navigate",u:"views-navigate-level-up.html",b:"Moves the level section to the next level up and says which level it is. Invisible on the ribbon; rebind it in the Shortcuts editor."},
{t:"Level Down",p:"Views > Navigate",u:"views-navigate-level-down.html",b:"Moves the level section to the next level down and says which level it is. Invisible on the ribbon; rebind it in the Shortcuts editor."},
{t:"Camera Sync",p:"Views > Navigate",u:"views-navigate-camera-sync.html",b:"Mirrors the camera live between two Navisworks windows on this computer, for two model versions side by side. Turn it on in both windows; the one you move leads."},
{t:"Coordinate Spotter",p:"Views > Navigate",u:"views-navigate-spotter-coordinate-spotter.html",b:"Click points in the view to drop numbered markers with their coordinates, then get the table, a clipboard copy and an Excel or CSV file. The clicks use the Measure tool, so the pointer snaps to vertices and edges exactly as a measurement does; Esc or right-click ends. Shift+Click sets a local origin."},
{t:"Clear Spots",p:"Views > Navigate",u:"views-navigate-spotter-clear-spots.html",b:"Removes the Coordinate Spotter markers from the view and starts the numbering again at P1."},
{t:"Sheet Overlay",p:"Views > Navigate",u:"views-navigate-sheet-sheet-overlay.html",b:"Draws a DXF plan over the model at a level, placed by offset and rotation or by two reference points, with its texts as labels. Once placed, one click shows it again; Shift+Click places another."},
{t:"Clear Sheet",p:"Views > Navigate",u:"views-navigate-sheet-clear-sheet.html",b:"Removes the DXF sheet overlay and its labels from the view."},
{t:"Clash Matrix",p:"Coordinate > Clash Setup",u:"coordinate-clash-setup-clash-matrix.html",b:"Builds a battery of clash tests from a workbook of trades and an H, C or D test matrix, referencing selection sets so the tests follow model updates. Can also write a template to fill in."},
{t:"Clash Templates",p:"Coordinate > Clash Setup",u:"coordinate-clash-setup-clash-templates.html",b:"Saves clash test definitions as named templates shared with your team, and builds them again in another model, naming any selection sets it cannot find."},
{t:"Scan vs Model",p:"Coordinate > Clash Setup",u:"coordinate-clash-setup-scan-vs-model.html",b:"Runs a clearance test between laser scans (points) and the design, then colours each design element by how close the scan comes and lists the closest ones."},
{t:"Clash Namer",p:"Coordinate > Clash Results",u:"coordinate-clash-results-clash-namer.html",b:"Renames clashes and result groups from a template like {test} {n:000} {grid} {level}, with a live before and after preview. Pick the tests, type the template, check the preview, then Rename. Shift+Click for settings."},
{t:"Status Rules",p:"Coordinate > Clash Results",u:"coordinate-clash-results-status-rules.html",b:"Applies ordered rules (depth, trades, age, element properties) that set clash statuses, assignees and comments, with a count of what each rule would change before anything is written."},
{t:"Clash Assigner",p:"Coordinate > Clash Results",u:"coordinate-clash-results-clash-assigner.html",b:"Assigns clash groups and ungrouped clashes to the trade that moves, keeps the ball-in-court history in the model, and shows who holds what and for how long. Shift+Click for settings."},
{t:"Clash to Viewpoints",p:"Coordinate > Clash Results",u:"coordinate-clash-results-clash-to-viewpoints.html",b:"Saves a viewpoint for each chosen clash or group, in folders by test and group, with a comment giving its status, distance, elements, grid and level."},
{t:"Clash Heatmap",p:"Coordinate > Clash Results",u:"coordinate-clash-results-clash-heatmap.html",b:"Colours elements by how many open clashes they have, lists the top hotspots, and can mark the densest spots in the view. Shift+Click clears the colours and markers."},
{t:"Show in Revit",p:"Coordinate > Clash Results",u:"coordinate-clash-results-revit-link-show-in-revit.html",b:"Sends the selected elements to Revit, where the Playground Link button for pyRevit selects and zooms to them."},
{t:"Show from Revit",p:"Coordinate > Clash Results",u:"coordinate-clash-results-revit-link-show-from-revit.html",b:"Selects and zooms to the elements sent from Revit with the Playground Link button for pyRevit."},
{t:"Clash Excel",p:"Coordinate > Clash Reports",u:"coordinate-clash-reports-clash-excel-report.html",b:"Writes a styled Excel report of the chosen clash tests: a summary in Clash Detective's colours, then one sheet per test with a thumbnail of each clash, filters and frozen headers."},
{t:"Clash Dashboard",p:"Coordinate > Clash Reports",u:"coordinate-clash-reports-clash-dashboard.html",b:"Builds a one-page HTML dashboard of the chosen clash tests (status, where the open clashes are, who holds them and for how long, groups and every clash) and opens it in your browser."},
{t:"Count Matrix",p:"Coordinate > Clash Reports",u:"coordinate-clash-reports-clash-count-matrix.html",b:"Counts open and new clashes trade against trade (or model against model) across the chosen tests, as heat tables in the output window and an optional workbook."},
{t:"Snapshot",p:"Coordinate > Clash Reports",u:"coordinate-clash-reports-history-snapshot-clashes.html",b:"Records the current results of the chosen clash tests as a snapshot that Clash Delta and Clash Trends compare with. Shift+Click to snapshot automatically on save, or to delete old snapshots."},
{t:"Clash Delta",p:"Coordinate > Clash Reports",u:"coordinate-clash-reports-history-clash-delta.html",b:"Compares the chosen clash tests now with a snapshot: new, fixed and still open clashes and status changes, in the output window and an optional workbook."},
{t:"Clash Trends",p:"Coordinate > Clash Reports",u:"coordinate-clash-reports-history-clash-trends.html",b:"Charts open and resolved clashes over the model's snapshots with a burn-down table, and can save it to Excel or CSV."},
{t:"Per-Trade Reports",p:"Coordinate > Clash Reports",u:"coordinate-clash-reports-per-trade-reports.html",b:"Writes one clash workbook (and an optional dashboard) per responsible trade into a folder, with an index, using Clash Assigner's who-moves list for unassigned clashes."},
{t:"Issues",p:"Coordinate > Issues",u:"coordinate-issues-issues.html",b:"The issue register of this model as a dock panel. Filter, sort and edit issues, go to their saved view, add comments, screenshots and pins, and raise a new issue from the current view."},
{t:"RFI",p:"Coordinate > Issues",u:"coordinate-issues-issue-stamps-rfi.html",b:"Click a point to raise a request for information there, from the RFI template, with the clicked object, the view and a snapshot. The click snaps like a measurement; Esc or right-click cancels."},
{t:"Hold",p:"Coordinate > Issues",u:"coordinate-issues-issue-stamps-hold.html",b:"Click a point to put a hold on work there, from the Hold template (high priority, due in 3 days by default), with the clicked object, the view and a snapshot. The click snaps like a measurement; Esc or right-click cancels."},
{t:"Verify",p:"Coordinate > Issues",u:"coordinate-issues-issue-stamps-verify.html",b:"Click a point to ask for a check on site or in the authoring model, from the Verify template, with the clicked object, the view and a snapshot. The click snaps like a measurement; Esc or right-click cancels."},
{t:"Safety",p:"Coordinate > Issues",u:"coordinate-issues-issue-stamps-safety.html",b:"Click a point to raise a safety concern there, from the Safety template (critical, due tomorrow by default), with the clicked object, the view and a snapshot. The click snaps like a measurement; Esc or right-click cancels."},
{t:"Stamp from Template",p:"Coordinate > Issues",u:"coordinate-issues-issue-stamps-stamp-from-template.html",b:"Choose any issue template, then click where the issue goes; the click snaps like a measurement, and Esc or right-click cancels. Templates are managed in Issue Templates."},
{t:"Issue Pins",p:"Coordinate > Issues",u:"coordinate-issues-issue-pins.html",b:"Shows every open issue that has a location as a pin in the view, labelled with its number, type and title. Each pin stands about a person tall, whatever the size of the model. The pins follow edits and come back when another model opens."},
{t:"Meeting Mode",p:"Coordinate > Issues",u:"coordinate-issues-meeting-mode.html",b:"Runs a coordination meeting through the issues you choose, one at a time, going to each in the view; change status, record decisions, reassign and set due dates as you go, then write the minutes as HTML and Excel."},
{t:"Issue Templates",p:"Coordinate > Issues",u:"coordinate-issues-issue-tools-issue-templates.html",b:"Manage the issue templates (type, number prefix, title pattern, priority, trade, assignee, due days, description, labels) that new issues, stamps and Clash to Issues start from. Shared with the team when a shared folder is set."},
{t:"Clash to Issues",p:"Coordinate > Issues",u:"coordinate-issues-issue-tools-clash-to-issues.html",b:"Turns each clash group and ungrouped clash of the chosen tests into an issue, once, with its clash view, snapshot and elements, and a trade, priority and due date from rules. Shift+Click for settings."},
{t:"Coordination Report",p:"Coordinate > Issues",u:"coordinate-issues-coordination-report.html",b:"Writes the issue register as an HTML page and an Excel workbook: open, overdue and due-this-week counts, open issues by trade, priority and age, the overdue list, a section per trade with snapshots, and what closed recently. Shift+Click for formats and folder."},
{t:"KPI Export",p:"Coordinate > Issues",u:"coordinate-issues-kpi-export.html",b:"Exports issues, comments, clash results, clash tests and clash history as CSV and JSON tables for Power BI, with a README describing every column. Shift+Click to set a fixed folder for scheduled refreshes."},
{t:"BCF Export",p:"Coordinate > BCF",u:"coordinate-bcf-bcf-export.html",b:"Writes Playground issues, or clash groups and clashes straight from Clash Detective, to a BCF 2.1 or 3.0 file with topics, comments, viewpoints in metres, IFC GUID components and snapshots, for Revit, Solibri, BIMcollab and other BCF tools."},
{t:"BCF Import",p:"Coordinate > BCF",u:"coordinate-bcf-bcf-import.html",b:"Reads a BCF 2.0, 2.1 or 3.0 file into the issue register, merging topics with the same GUID, saving their viewpoints under BCF in Saved Viewpoints and finding their components by IFC GUID or Revit Element ID."},
{t:"Batch Append",p:"Project > Models",u:"project-models-batch-append.html",b:"Appends many model files at once from a folder (optionally with its subfolders) or from a manifest list (txt, csv or xlsx with optional order and trade columns), after a preview that ticks only the files not appended yet."},
{t:"Source Files",p:"Project > Models",u:"project-models-source-files.html",b:"A panel listing every appended model with its type, units, file time and item count, flagging files that are out of date or missing. Tick to show or hide a model; isolate, select, zoom, open its folder, refresh changed files or remove models from here."},
{t:"Link Navigator",p:"Project > Models",u:"project-models-link-navigator.html",b:"From the selected element to the model it comes from: its files, units, transform, freshness and size in the output window, then select, isolate, hide, open the folder, refresh, remove it or show it in Source Files."},
{t:"Transform Fixer",p:"Project > Models",u:"project-models-transform-fixer.html",b:"Moves, turns about Z, re-units or resets whole models by typed values or two picked points, as one undo step, and saves or applies a transform preset per model file (optionally applied whenever that file is appended)."},
{t:"Folder Watch",p:"Project > Models",u:"project-models-folder-watch.html",b:"Watches the files of the appended models and, when one changes on disk, offers to refresh it with a small notice that never takes focus. Shift+Click to choose the folders, how often to check and whether to start with Navisworks."},
{t:"Stale Files",p:"Project > Models",u:"project-models-stale-file-alert.html",b:"Compares every model's loaded file (the NWC) with its source file and lists the models whose source was saved later, whose file is missing, or whose source is not on this computer. Shift+Click to check automatically whenever a model opens."},
{t:"Health Check",p:"Project > Quality",u:"project-quality-model-health-check.html",b:"Scores every appended model from 0 to 100 on units, distance from the origin, far-away objects, element IDs, duplicate appends, transforms and file age, with an HTML and Excel report. Shift+Click to set the thresholds and report formats."},
{t:"Duplicate Finder",p:"Project > Quality",u:"project-quality-duplicate-finder.html",b:"Finds objects that are the same thing in the same place, within one model or across appended models, then selects the extra copies and saves them as a selection set."},
{t:"Model Compare",p:"Project > Quality",u:"project-quality-model-compare.html",b:"Compares two appended versions of a model, or a model with a snapshot you saved earlier, matching objects by their IDs. Added objects turn green, changed amber and removed red, with Compare selection sets and an Excel list."},
{t:"Preflight",p:"Project > Quality",u:"project-quality-preflight.html",b:"Checks the document is ready to share against a profile: saved, models current, clash tests run after the newest models, no stray hidden items, overrides or section. Shift+Click to edit the profiles."},
{t:"Session Stats",p:"Project > Quality",u:"project-quality-session-stats.html",b:"Measures every appended model (file sizes, items, geometry items, primitives, fragments, extent, units, when it arrived and how long it took to load) in a table and a chart, and saves the table as an Excel workbook beside the document."},
{t:"NWD Publisher",p:"Project > Publish",u:"project-publish-nwd-publisher.html",b:"Publishes the document as a numbered NWD with title, author and expiry, after a Preflight, and moves older versions into an Archive folder."},
{t:"Model Wipe",p:"Project > Publish",u:"project-publish-model-wipe.html",b:"Removes the kinds of data you choose from the document, such as saved viewpoints, selection sets, clash tests, overrides and Playground data, after showing exactly how much will go."},
{t:"TimeLiner from Excel",p:"Project > 4D",u:"project-4d-timeliner-from-excel.html",b:"Builds or updates TimeLiner tasks from an Excel or CSV schedule (Task ID, Parent ID or WBS, dates, task type, attachments, progress), checking every row before anything changes. Write a template first to start from the tasks already in the model."},
{t:"Auto Attach",p:"Project > 4D",u:"project-4d-auto-attach.html",b:"Attaches model items to TimeLiner tasks by rules, such as task names like L3 Ducts to items on Level 3 in the duct layer, or names containing Slab to a selection set. Previews every task first and attaches in one undo step. Shift+Click loads saved rule templates."},
{t:"Progress Painter",p:"Project > 4D",u:"project-4d-progress-painter.html",b:"Sets the percent complete of the selected objects (a Playground > Progress property) and updates the TimeLiner progress of the tasks that hold them, or paints the model in four progress bands with a legend."},
{t:"4D Movie Maker",p:"Project > 4D",u:"project-4d-movie-maker.html",b:"Renders a construction sequence from TimeLiner dates and task types, one stamped frame per day or week, as PNG frames, an HTML player and an MP4 when ffmpeg is installed. Visibility and colours are put back exactly afterwards, even on cancel."},
{t:"TimeLiner Export",p:"Project > 4D",u:"project-4d-schedule-tools-timeliner-export.html",b:"Exports every TimeLiner task to a styled Excel workbook: outline numbers and indented names, planned and actual dates, durations, type, progress, status, attachments and user columns."},
{t:"Schedule Health",p:"Project > 4D",u:"project-4d-schedule-tools-schedule-health.html",b:"Checks the TimeLiner schedule for tasks with nothing attached, missing or reversed dates, zero durations, objects in several tasks and objects in no task, scores it out of 100 and opens the report. Shift+Click for options."},
{t:"Quick Takeoff",p:"Project > Quantities",u:"project-quantities-quick-takeoff.html",b:"Counts and measures objects (length, area, volume, weight from Revit and IFC properties, or from geometry) grouped by one or two properties, with subtotals and totals. Export to Excel, select any group, or save the setup as a template."},
{t:"Zone Takeoff",p:"Project > Quantities",u:"project-quantities-zone-takeoff.html",b:"Measures objects by zone, from grid levels, rooms or areas, grid bays or square tiles, and by group. Exports an Excel pivot with a sheet per zone."},
{t:"Takeoff Templates",p:"Project > Quantities",u:"project-quantities-takeoff-templates.html",b:"Lists the saved Quick and Zone Takeoff templates, shared with the team when Playground uses a shared folder. Run, rename, duplicate, delete, export or import them."},
{t:"COG Calculator",p:"Project > Quantities",u:"project-quantities-cog-calculator.html",b:"Weighs the selected objects from closed-mesh volumes and material densities (or their Weight property), marks the combined centre of gravity in the view and lists every object with its weight, centroid and method. Shift+Click for densities."},
{t:"QR Tagger",p:"Project > Field",u:"project-field-qr-tagger.html",b:"Makes a QR code for each selected object from a payload template (project, file, Element ID, IFC GUID or a URL), saved as PNG files with a printable A4 label sheet, and writes the payload into the object as Playground > QR."},
{t:"Photo Pins",p:"Project > Field",u:"project-field-photo-pins.html",b:"Pins site photos to a point in the model, with a caption and the level, grid and object found there, and draws the pins in the view. Click the point, choose the photos, then type a caption. Shift+Click for settings."},
{t:"Photo Browser",p:"Project > Field",u:"project-field-photo-browser.html",b:"Shows this model's photo pins as thumbnails grouped by level, grid or linked object. Filter them, go to a pin's view and object, open a photo, delete a pin or export an HTML photo report."},
{t:"Field Checklists",p:"Project > Field",u:"project-field-field-checklists.html",b:"Inspection checklists attached to saved viewpoints: Pass, Fail or N/A with notes per item, inspector, date and sign-off, stepping from viewpoint to viewpoint, with an HTML and Excel report. Shift+Click edits the team's templates."},
{t:"Geometry Exporter",p:"Project > Exchange",u:"project-exchange-geometry-exporter.html",b:"Exports the selected objects' own triangles with their colours to glTF (.glb), OBJ, STL or DXF 3D faces, adding IDs and chosen properties in glTF. Big selections are budgeted and anything skipped is listed."},
{t:"IFC Exporter",p:"Project > Exchange",u:"project-exchange-ifc-exporter.html",b:"Writes the selected objects to an IFC4 file with storeys from their levels, IFC classes from their categories, colours, GlobalIds and property sets. Shift+Click to change which IFC class a category becomes."},
{t:"Command Palette",p:"Dev > Automate",u:"dev-automate-command-palette.html",b:"Type a few letters to run any pyNavis or Navisworks command, go to a saved view or select a set. Recently used ones come first."},
{t:"Record Macro",p:"Dev > Automate",u:"dev-automate-macro-record.html",b:"Records the pyNavis commands you run next, so Play Macro can repeat them in order."},
{t:"Play Macro",p:"Dev > Automate",u:"dev-automate-macros-play-macro.html",b:"Runs a saved macro, one command after another. Dialogs inside its commands still ask you; click again to stop a playing macro."},
{t:"Manage Macros",p:"Dev > Automate",u:"dev-automate-macros-manage-macros.html",b:"Rename, reorder, add pauses, questions or Navisworks commands to, export or import your macros."},
{t:"Macro to Button",p:"Dev > Automate",u:"dev-automate-macros-macro-to-button.html",b:"Makes a ribbon button in your MyTools extension that plays a macro, with its own icon and shortcut."},
{t:"Report Templates",p:"Dev > Reports",u:"dev-reports-report-templates.html",b:"Every saved template of every Playground report in one list, to run without dialogs, edit, duplicate, delete, export or import. Reports not built yet show as unavailable."},
{t:"Scheduled Reports",p:"Dev > Reports",u:"dev-reports-scheduled-reports.html",b:"Runs report templates on a model on a timetable through Windows Task Scheduler and the pyNavis command line runner, then mails or copies the results."},
{t:"Button Maker",p:"Dev > Build",u:"dev-build-button-maker.html",b:"Makes a new ribbon button in your MyTools extension from a template or your own script, with an icon and an optional shortcut."},
{t:"Script Editor",p:"Dev > Build",u:"dev-build-script-editor.html",b:"Edits the scripts of your own extensions beside Navisworks, with line numbers, completion, a syntax check on save and F5 to run."},
{t:"Hotkey Manager",p:"Dev > Build",u:"dev-build-hotkey-manager.html",b:"Gives any pyNavis button or Navisworks ribbon command a keyboard shortcut, or takes one away, and warns when two commands want the same keys. Click a command, click the shortcut field, then press the keys."},
{t:"Extension Manager",p:"Dev > Team",u:"dev-team-extension-manager.html",b:"Installs, updates and removes pyNavis extensions listed in your team registry. Shift+Click sets the registry."},
{t:"Team Sync",p:"Dev > Team",u:"dev-team-team-sync.html",b:"Pulls the team's templates, presets, rules, shortcuts and project settings from the team folder, or pushes yours to it."},
{t:"Usage Analytics",p:"Dev > Team",u:"dev-team-usage-analytics.html",b:"Shows which tools are used, when and by whom, and which are never used. Opt-in, and it never records document names. Shift+Click for settings and Excel export."},
{t:"Environment Doctor",p:"Dev > Team",u:"dev-team-team-tools-environment-doctor.html",b:"Checks Navisworks, pyNavis, engines, extensions, shortcuts, panels, add-ins, folders and the log, and reports what needs attention. Shift+Click copies the report as text."},
{t:"Playground Settings",p:"Dev > Team",u:"dev-team-team-tools-playground-settings.html",b:"Sets your name, the project and company, where Playground keeps team data, the trades and trade rules, report units and the date format."},
{t:"Unit Converter",p:"Dev > Tools",u:"dev-tools-unit-converter.html",b:"Converts lengths, areas, volumes and masses as you type, like 12' 6\" to mm or 250 sqft in m2. Enter copies the result."}
];
